/*
  POS Terminali - Nihai Ajan Operasyon Sistemi
  - Açılış: 'A' Tuşu -> Şifre İstemi (190419)
  - Ana Menü Matrisi: 4 Sütun x 8 Satır Uygulama Düzeni
  - Uygulama Sıralaması: 
    1. Hesap Makinesi, 2. Wi-Fi Tarayıcı, 3. Yılan Oyunu (TSSSS!), 
    4. Tetris, 5. Yapay Zeka, 6. Kilometre Ölçer, 7. Kronometre
  - Üst Dokunmatik Gizlilik Kilidi: GPIO 4
  - Yapay Zeka Navigasyon: 2 (Yukarı), 6 (Sağ), 4 (Sol), 0 (Aşağı), 5 (OK)
*/

#include <WiFi.h>

const int touchPin = 4;        // Üst taraftaki dokunmatik gizlilik kilidi
const int touchThreshold = 40; // Dokunma hassasiyet eşiği

// Menü ve Sistem Durumları
enum State {
  BEKLEME_ACILIS,
  SIFRE_KONTROL,
  ANA_MENU_MATRIS,
  HESAP_MAKINESI,
  WIFI_TARAYICI,
  YILAN_OYUNU,
  TETRIS,
  YAPAY_ZEKA,
  KILOMETRE_OLCER,
  KRONOMETRE
};

State currentState = BEKLEME_ACILIS;
bool gizlilikKilidiAktif = false;
String girisTamponu = "";

// Kilometre ve Kronometre değişkenleri
unsigned long kiloBaslangicZamani = 0;
unsigned long kronometreBaslangic = 0;

// Fonksiyon Bildirimleri (Void Tanımları)
void matrisMenuyuGoster();
void wifiTara();
void yapayZekayiBaslat();
void yapayZekaCevapVer();

void setup() {
  Serial.begin(115200);
  delay(1000);

  Serial.println("\n==========================================");
  Serial.println("   GİZLİ AJAN TERMİNALİ - GÜVENLİ MOD       ");
  Serial.println("==========================================");
  Serial.println("Cihazı açmak için klavyeden 'A' tuşuna basın...");
}

void loop() {
  // 1. Üst taraftaki dokunmatik gizlilik kilidi kontrolü
  if (touchRead(touchPin) < touchThreshold) {
    if (!gizlilikKilidiAktif) {
      gizlilikKilidiAktif = true;
      Serial.println("\n[!] GİZLİLİK KİLİDİ DEVREDE - Ekran Gizlendi!");
    }
    delay(300);
    return;
  } else if (gizlilikKilidiAktif) {
    gizlilikKilidiAktif = false;
    Serial.println("\n[OK] Gizlilik Kilidi Kaldırıldı.");
    if (currentState >= ANA_MENU_MATRIS) {
      matrisMenuyuGoster();
    }
  }

  if (Serial.available() > 0) {
    char c = Serial.read();
    if (c == '\n' || c == '\r') return;

    // --- AÇILIŞ ('A' TUŞU) ---
    if (currentState == BEKLEME_ACILIS) {
      if (c == 'A' || c == 'a') {
        currentState = SIFRE_KONTROL;
        girisTamponu = "";
        Serial.println("\n[GÜVENLİK] Sistem erişim şifresini giriniz (Şifre + #):");
      } else {
        Serial.println("Sistemi açmak için lütfen 'A' tuşuna basın.");
      }
    }

    // --- ŞİFRE KONTROLÜ (190419#) ---
    else if (currentState == SIFRE_KONTROL) {
      if (c == '#') {
        if (girisTamponu == "190419") {
          currentState = ANA_MENU_MATRIS;
          Serial.println("\n[BAŞARILI] Şifre onaylandı. Ana matris yükleniyor...");
          matrisMenuyuGoster();
        } else {
          Serial.println("\n[HATA] Yanlış şifre! Tekrar deneyin:");
          girisTamponu = "";
        }
      } else {
        girisTamponu += c;
        Serial.print(c);
      }
    }

    // --- ANA MENÜ MATRİSİ (4 Sütun x 8 Satır Düzeni) ---
    else if (currentState == ANA_MENU_MATRIS) {
      if (c == '1') {
        currentState = HESAP_MAKINESI;
        girisTamponu = "";
        Serial.println("\n--- [1] HESAP MAKİNESİ AKTİF ---");
        Serial.println("İşlem yapabilirsiniz. Ana menüye dönmek için '0' tuşlayın.");
      } else if (c == '2') {
        currentState = WIFI_TARAYICI;
        Serial.println("\n--- [2] WI-FI TARAYICI AKTİF ---");
        wifiTara();
        Serial.println("Ana menüye dönmek için '0' tuşlayın.");
      } else if (c == '3') {
        currentState = YILAN_OYUNU;
        Serial.println("\n--- [3] YILAN OYUNU (TSSSS!) YÜKLENDİ ---");
        Serial.println("Ana menüye dönmek için '0' tuşlayın.");
      } else if (c == '4') {
        currentState = TETRIS;
        Serial.println("\n--- [4] TETRİS BAŞLATILDI ---");
        Serial.println("Ana menüye dönmek için '0' tuşlayın.");
      } else if (c == '5') {
        currentState = YAPAY_ZEKA;
        yapayZekayiBaslat();
      } else if (c == '6') {
        currentState = KILOMETRE_OLCER;
        kiloBaslangicZamani = millis();
        Serial.println("\n--- [6] KİLOMETRE ÖLÇER AKTİF ---");
        Serial.println("Ölçüm başlatıldı! Ana menüye dönmek için '0' tuşlayın.");
      } else if (c == '7') {
        currentState = KRONOMETRE;
        kronometreBaslangic = 5;
        Serial.println("\n--- [7] KRONOMETRE AKTİF (5 ile başladı) ---");
        Serial.println("Kaydetmek için 'B' tuşuna basın. Ana menüye dönmek için '0' tuşlayın.");
      } else {
        Serial.println("Geçersiz uygulama seçimi! 1-7 arası tuşlayın.");
      }
    }

    // --- UYGULAMA 1: HESAP MAKİNESİ ---
    else if (currentState == HESAP_MAKINESI) {
      if (c == '0') {
        currentState = ANA_MENU_MATRIS;
        matrisMenuyuGoster();
      } else {
        Serial.print("Hesap Girdisi: ");
        Serial.println(c);
      }
    }

    // --- UYGULAMA 2: Wİ-Fİ ---
    else if (currentState == WIFI_TARAYICI) {
      if (c == '0') {
        currentState = ANA_MENU_MATRIS;
        matrisMenuyuGoster();
      }
    }

    // --- UYGULAMA 3: YILAN OYUNU ---
    else if (currentState == YILAN_OYUNU) {
      if (c == '0') {
        currentState = ANA_MENU_MATRIS;
        matrisMenuyuGoster();
      }
    }

    // --- UYGULAMA 4: TETRİS ---
    else if (currentState == TETRIS) {
      if (c == '0') {
        currentState = ANA_MENU_MATRIS;
        matrisMenuyuGoster();
      }
    }

    // --- UYGULAMA 5: YAPAY ZEKA ---
    else if (currentState == YAPAY_ZEKA) {
      if (c == '2') {
        Serial.println(" [Yön: YUKARI]");
      } else if (c == '6') {
        Serial.println(" [Yön: SAĞ]");
      } else if (c == '4') {
        Serial.println(" [Yön: SOL]");
      } else if (c == '0') {
        Serial.println(" [Yön: AŞAĞI]");
      } else if (c == '5') {
        Serial.println(" [OK Tuşu Basıldı] İstihbarat sorgulanıyor...");
        yapayZekaCevapVer();
      } else if (c == 'X' || c == 'x') {
        currentState = ANA_MENU_MATRIS;
        matrisMenuyuGoster();
      } else {
        Serial.print("Klavye harf seçimi: ");
        Serial.println(c);
      }
    }

    // --- UYGULAMA 6: KİLOMETRE ÖLÇER ---
    else if (currentState == KILOMETRE_OLCER) {
      if (c == '0') {
        currentState = ANA_MENU_MATRIS;
        matrisMenuyuGoster();
      }
    }

    // --- UYGULAMA 7: KRONOMETRE ---
    else if (currentState == KRONOMETRE) {
      if (c == 'B' || c == 'b') {
        Serial.println("\n[KRONOMETRE] Değer başarıyla 'B' tuşu ile kaydedildi!");
      } else if (c == '0') {
        currentState = ANA_MENU_MATRIS;
        matrisMenuyuGoster();
      }
    }
  }
}

// --- MENÜ VE İŞLEM FONKSİYONLARI ---

void matrisMenuyuGoster() {
  Serial.println("\n==================================================");
  Serial.println("      ANA MATRİS MENÜ (4 Sütun x 8 Satır Düzeni)    ");
  Serial.println("==================================================");
  Serial.println("  [1] Hesap Makinesi      [5] Yapay Zeka");
  Serial.println("  [2] Wi-Fi Tarayıcı      [6] Kilometre Ölçer");
  Serial.println("  [3] Yılan (TSSSS!)      [7] Kronometre");
  Serial.println("  [4] Tetris");
  Serial.println("--------------------------------------------------");
  Serial.println("Gitmek istediğiniz uygulama numarasını tuşlayın...");
}

void wifiTara() {
  Serial.println("\n[Wi-Fi] Çevredeki ağlar taranıyor...");
  WiFi.mode(WIFI_STA);
  WiFi.disconnect();
  delay(100);
  int agSayisi = WiFi.scanNetworks();
  if (agSayisi == 0) {
    Serial.println("Hiçbir Wi-Fi ağı bulunamadı.");
  } else {
    for (int i = 0; i < agSayisi; ++i) {
      Serial.print(i + 1);
      Serial.print(": ");
      Serial.print(WiFi.SSID(i));
      Serial.print(" (Sinyal: ");
      Serial.print(WiFi.RSSI(i));
      Serial.println(" dBm)");
    }
  }
}

void yapayZekayiBaslat() {
  Serial.println("\n--- [5] YAPAY ZEKA (SANAL KLAVYE AKTİF) ---");
  Serial.println("Kontroller: 2 (Yukarı), 6 (Sağ), 4 (Sol), 0 (Aşağı), 5 (OK)");
  Serial.println("Ana menüye dönmek için 'X' tuşuna basın.");
}

void yapayZekaCevapVer() {
  if (WiFi.status() == WL_CONNECTED) {
    Serial.println("AI (Çevrimiçi): Bulut verileri işleniyor...");
  } else {
    Serial.println("AI (Çevrimdışı - Motivasyon Modu):");
    Serial.println("-> 'Asla pes etme, ajan!'");
    Serial.println("-> 'Hedefe odaklan, kararlılık başarıyı getirir.'");
  }
}
